import sys, json, math
class Solution:
    def judgeSquareSum(self, c: int) -> bool:
        a, b = 0, math.isqrt(c)
        while a <= b:
            s = a * a + b * b
            if s == c: return True
            if s < c: a += 1
            else: b -= 1
        return False

